import * as T from './vendor/three.module.min.js';
import{makeTaskGate}from'./task-gates.js';
import{WorldMechanism,mechanismPlacement}from'./world-mechanisms.js';
import{taskFraction}from'./trail-tasks.js';
// One permanent obstacle owns the reading leaves. Only its hinged leaves unfold;
// the obstacle is never exchanged for a larger task-stage model.
export class ContinuousMechanism{
 constructor(scene,node,area=0,completed=false){this.node=node;this.root=new T.Group();this.root.name='continuous-'+node.type;this.root.userData.placeId=node.id;const pose=mechanismPlacement(node);this.root.position.copy(pose.position);this.root.rotation.y=pose.yaw;scene.add(this.root);this.gate=makeTaskGate(node.type,{area});this.root.add(this.gate.group);this.stage=new WorldMechanism(scene);this.stage.mount=this;this.stage.area=area;this.value=this.target=completed?1:0;this.amount=0;this.reading=false;this.time=0;this.prepared=false;this.gate.update(this.value,0);Object.assign(this.gate.group.userData,{completed,blocking:!completed,progress:this.value});
  const material=new T.MeshStandardMaterial({color:'#857453',roughness:.8});this.supportMaterial=material;this.arms=[];this.armGeometry=new T.CylinderGeometry(1,1,1,6);this.posts=[];for(const x of[-3.35,3.35]){const post=new T.Mesh(new T.CylinderGeometry(.055,.08,3.28,8),material);post.position.set(x,1.64,.6);post.castShadow=true;this.root.add(post);this.posts.push(post);const hinge=new T.Mesh(new T.CylinderGeometry(.10,.10,.20,10),material);hinge.rotation.z=Math.PI/2;hinge.position.set(x,3.28,.6);this.root.add(hinge);}const rail=new T.Mesh(new T.BoxGeometry(6.9,.10,.16),material);rail.position.set(0,3.28,.6);this.root.add(rail);this.root.updateMatrixWorld(true);const bounds=new T.Box3().setFromObject(this.gate.group),local=this.root.worldToLocal(new T.Vector3(bounds.max.x,bounds.max.y,bounds.max.z));this.panelDepth=Math.max(.8,Math.min(3,Math.abs(local.z)+.45));
 }
 prepare(task,viewport){this.stage.readingViewport=viewport;const plan=this.stage.render(task,this.node);this.gate.setTask(task,{immediate:!this.prepared});this.target=taskFraction(task);if(!this.prepared){this.value=this.target;this.prepared=true;}this.foldLeaves();return plan;}
 enter(task,viewport){const plan=this.prepare(task,viewport);if(!this.reading)this.stage.entryAge=0;this.reading=true;this.stage.reading=true;return plan;}
 leave(){this.reading=false;this.stage.reading=false;this.stage.releasePress?.();this.stage.releasePress=null;this.stage.pressLayer=null;}
 update(dt){this.time+=dt;this.amount=Math.max(0,Math.min(1,this.amount+(this.reading?dt/.82:-dt/.65)));const step=dt/2.1;this.value+=Math.max(-step,Math.min(step,this.target-this.value));this.gate.update(this.value,this.time);Object.assign(this.gate.group.userData,{completed:this.value===1,blocking:this.value<1,progress:this.value});if(!this.reading)this.stage.update(dt);this.foldLeaves();}
 foldLeaves(){if(!this.stage.root)return;const f=this.amount*this.amount*(3-2*this.amount);let i=0;for(const v of this.stage.entries.values()){if(v.entry.placed)continue;const p=new T.Vector3(0,3.45+i*.10,-.55-(i%3)*.12),q=new T.Quaternion().setFromAxisAngle(new T.Vector3(1,0,0),-Math.PI/2);if(this.amount<1){v.mesh.position.copy(p).lerp(v.target,f);v.mesh.quaternion.copy(q).slerp(v.targetQuaternion,f);}let arm=this.arms[i];if(!arm){arm=new T.Mesh(this.armGeometry,this.supportMaterial);arm.name="reading-leaf-strut";this.root.add(arm);this.arms.push(arm);}v.mesh.updateWorldMatrix(true,false);const end=this.root.worldToLocal(v.mesh.localToWorld(new T.Vector3(0,v.entry.h/2,-.14))),start=new T.Vector3(Math.max(-3.25,Math.min(3.25,v.entry.x)),3.28,.6),delta=end.clone().sub(start),length=delta.length();arm.visible=true;arm.position.copy(start).addScaledVector(delta,.5);arm.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),delta.normalize());arm.scale.set(.018,Math.max(.001,length),.018);i++;}for(let k=i;k<this.arms.length;k++)this.arms[k].visible=false;for(const cable of this.stage.linkMap.values())cable.visible=this.amount>.98;this.root.updateMatrixWorld(true);}
 frameCamera(pose,width,height,viewport){const b=this.bodyBounds||{halfWidth:1.526,halfDepth:1.4},bodyHeight=this.bodyHeight||2.18,key=JSON.stringify([width,height,viewport,b,bodyHeight]);if(this.cameraKey===key&&this.cameraPlan===this.stage.plan)return this.cameraPose;const points=[],root=this.stage.root;for(const v of this.stage.entries.values()){const e=v.entry;if(e.placed)continue;for(const x of[-e.w/2,e.w/2])for(const y of[-e.h/2,e.h/2])points.push({p:root.localToWorld(new T.Vector3(e.x+x,e.y+y,e.z+.17)),label:true});}const seat=Math.max(3.1,b.halfDepth+1);for(const x of[-b.halfWidth,b.halfWidth])for(const y of[0,bodyHeight])for(const z of[-b.halfDepth,b.halfDepth])points.push({p:root.localToWorld(new T.Vector3(-.8+x,y,seat+z)),label:false});const camera=new T.PerspectiveCamera(pose.fov,width/height,.1,250),direction=pose.position.clone().sub(pose.target),target=pose.target.clone();target.y-=Math.min(.6,this.stage.plan.height*.06);let factor=1;for(let i=0;i<50;i++){camera.position.copy(target).addScaledVector(direction,factor);camera.lookAt(target);camera.setViewOffset(width,height,pose.offset.x,pose.offset.y,width,height);camera.updateMatrixWorld(true);const fits=points.every(q=>{const p=q.p.clone().project(camera),x=(p.x*.5+.5)*width,y=(-p.y*.5+.5)*height;return q.label?x>=viewport.left&&x<=width-viewport.right&&y>=viewport.top&&y<=height-viewport.bottom:Math.abs(p.x)<.96&&Math.abs(p.y)<.96;});if(fits)break;factor*=1.025;}this.cameraKey=key;this.cameraPlan=this.stage.plan;this.cameraPose={...pose,position:camera.position.clone(),target};return this.cameraPose;}
 solids(){return this.posts.map(post=>{const p=post.getWorldPosition(new T.Vector3());return{x:p.x,z:p.z,r:.10,top:3.35,kind:'mechanism-post'};});}
 dispose(){this.stage.clear();this.root.removeFromParent();const geometries=new Set(),materials=new Set();this.root.traverse(o=>{if(o.geometry)geometries.add(o.geometry);for(const m of Array.isArray(o.material)?o.material:o.material?[o.material]:[])materials.add(m);});for(const g of geometries)g.dispose();for(const m of materials)m.dispose();}
}
